#include <stdio.h>
#include <string.h>

void fragil(char *entrada) {
    char nome[16];            // 16 bytes na pilha, e olhe lá
    strcpy(nome, entrada);    // copia até acabar o texto. Não olha o tamanho.
    printf("Olá, %s\n", nome);
}

void firme(char *entrada) {
    char nome[16];
    snprintf(nome, sizeof nome, "%s", entrada);   // no máximo 16, sempre
    printf("Olá, %s\n", nome);
}

// com uma entrada de 200 caracteres, o strcpy escreve 200 bytes
// num espaço de 16. Os outros 184 vão por cima do que estava depois
// na pilha, inclusive do endereço de volta da função.

desafio.solucao:
def copiar(destino, itens):
    for i, item in enumerate(itens):
        destino[i] = item      # aqui o Python confere o limite
    return destino

caixa = [None] * 4
print(copiar(caixa, [1, 2, 3, 4]))
# [1, 2, 3, 4]

try:
    copiar(caixa, [1, 2, 3, 4, 5, 6])
except IndexError as erro:
    print("parou:", erro)
# parou: list assignment index out of range

# a pilha também tem limite, e dá pra ver:
def fundo(n=0):
    return fundo(n + 1)

try:
    fundo()
except RecursionError:
    print("a pilha acabou antes da recursão")

# o que teria acontecido em C sem checagem:
# nada de erro. Os itens 5 e 6 seriam escritos logo depois da caixa,
# por cima do que estivesse ali: outra variável, um ponteiro, ou o
# endereço de volta da função.
# o programa continuaria rodando com a memória adulterada, e o efeito
# apareceria em outro lugar, muito depois. É por isso que essa família
# de erro é tão difícil de achar e tão explorada.
